  48    id: string;
  49    /** 原始或清洗前的展示文件名。 */
  50    name: string;
  51    /** MIME 类型（可用时）。 */
  52    mime?: string;
  53    /** 字节大小（可用时）。 */
  54    size?: number;
  55    /** 渠道侧落盘引用路径（内部物化使用，历史工具不对外暴露本机路径）。 */
  56    sourceRef: string;
  57    /** 渠道下载是否成功。 */
  58    state: 'available' | 'unavailable';
  59    /** 下载失败原因。 */
