  74  export interface ChannelOrigin {
  75    /** 渠道名（feishu / wechat / http / cli）。 */
  76    channel: string;
  77    /** 深拷贝的原渠道地址对象。 */
  78    address: Record<string, unknown>;
  79  }
  80  
  81  
  82  /** 来源可见域与授权范围。 */
  83  export interface ChannelVisibility {
  84    /** 作用域字符串描述。 */
  85    scope: string;
  86    /** 是否受信任作用域（如私聊或 trusted 群）。 */
  87    trusted: boolean;
  88    /** 显式配置的公共源白名单。 */
  89    publicSourceIds: string[];
  90  }
  91  
  92  
  93  /** 单机器人路由附带信息。 */
  94  export interface BotRoutingHint {
  95    /** 该机器人在这条消息上是否仅监听当背景。 */
  96    listenOnly: boolean;
  97    /** 是否由决策模型判断是否接话。 */
  98    judge?: boolean;
  99  }
 100  
 101  
 102  /** 渠道路由建议。 */
 103  export interface ChannelRouting {
 104    /** 默认是否仅监听当背景。 */
 105    listenOnly: boolean;
 106    /** 默认是否由决策模型判断。 */
 107    judge?: boolean;
 108    /** 服务端校验过的指定会话号：bots 只投给这场会话的机器人、进这场会话（网页“发给哪个会话”、引用别的渠道的消息）。 */
 109    sessionId?: string;
 110    /** 引用别的渠道的消息时，被引那条的原渠道、原机器人、原会话（入口校验过）；只作记录，回话照旧回本条来源。 */
 111    replyOrigin?: { source: string; bot: string; sessionId: string };
 112    /** 一轮一次 channel_reply 都没调时，把最后的话当 final 直接发出去（一对一的渠道：网页、命令行、微信）；不写走修复轮。 */
 113    autoFinal?: boolean;
 114    /** 多机器人场景下每个机器人各自的监听/判断覆盖项。 */
 115    byBot?: Record<string, BotRoutingHint>;
 116  }
 117  
 118  
 119  /** 网页发话时附带的当前查看上下文（供 131 接入 POST /api/message 的 view 后填入）。 */
 120  export interface ChannelView {
 121    /** 网页当前正在查看的渠道名（feishu / wechat / http / cli）。 */
 122    channel: string;
 123    /** 网页当前正在查看的聊天标识；看的是整个渠道时是 ''。 */
 124    chat: string;
 125    /** 给人看的名字（web-api 照 /api/channels 的清单填）：“飞书·群·测试群”“飞书·全部聊天”；前台这一轮的提示里用它。 */
 126    label?: string;
 127  }
 128  
 129  
```

### 解释
- 都是纯类型，按声明顺序拆成八个子块。

### 调到别处
无（类型声明）

