 638  export function decodeHistoryCursor(
 639    cursor: string,
 640    expected: Omit<HistoryCursorPayload, 'beforeAt' | 'beforeId'>,
 641  ): HistoryCursorPayload | undefined {
 642    const dot = cursor.indexOf('.');
 643    if (dot <= 0) return undefined;
 644  
 645    const raw = cursor.slice(0, dot);
 646    const sig = cursor.slice(dot + 1);
 647    const actualSig = crypto.createHmac('sha256', CURSOR_SECRET).update(raw).digest('base64url');
 648    if (sig.length !== actualSig.length) return undefined;
 649  
